$t_0(x) = x$, $t_1(x) = \tan x$, and $t_{-1}(x) = \tanh x$ for all $x$;
  similarly $s_0(x)=x$, $s_1=\sin$, $s_{-1}=\sinh$ and $c_0=1$, $c_1=\cos$,
  $c_{-1}=\cosh$ (simp lemmas per case).

$\mathrm{ModerateArc}\,K\,\kappa\,\ell$ holds when for every
  $i\in\mathbb{Z}/n$:
  \begin{enumerate}
  \item $0 < \ell_i$;
  \item (positive branch) $0 < s_K(\ell_i/2)$ and $0 < c_K(\ell_i/2)$;
  \item (strict wall) $|\kappa_i|\cdot t_K(\ell_{i-1}/2) < 1$ and
        $|\kappa_i|\cdot t_K(\ell_i/2) < 1$.
  \end{enumerate}

lean.code:
def ModerateArc (K : ℝ) (κ ℓ : ZMod n → ℝ) : Prop :=
  ∀ i : ZMod n, 0 < ℓ i ∧ 0 < sK K (ℓ i / 2) ∧ 0 < cK K (ℓ i / 2) ∧
    |κ i| * tK K (ℓ (i - 1) / 2) < 1 ∧ |κ i| * tK K (ℓ i / 2) < 1

namespace ModerateArc

variable {K : ℝ} {κ ℓ : ZMod n → ℝ}

blocks.body:
Under $\mathrm{ModerateArc}\,K\,\kappa\,\ell$, for each $i$: $0 < \ell_i$;
  $0 < t_K(\ell_i/2)$; and the two strict walls
  $|\kappa_i|\cdot t_K(\ell_{i-1}/2) < 1$, $|\kappa_i|\cdot t_K(\ell_i/2) < 1$.

lean.code:
lemma turningAngle_eq_zero {K : ℝ} {κ ℓ : ZMod n → ℝ} {i : ZMod n}
    (hκ : κ i = 0) : turningAngle K κ ℓ i = 0 := by
  simp [turningAngle, hκ]

